-- Esquema MÍNIMO do legado (só tabelas/colunas usadas pela Fase 1) para testes locais.
-- NÃO usar em produção: lá as tabelas já existem.
CREATE TABLE INSTITUICAO (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, FANTASIA VARCHAR(200), TITULO VARCHAR(200), EMAIL VARCHAR(200),
  URL VARCHAR(200), LOGO VARCHAR(500), COR_PRIMARIA VARCHAR(20), CELULAR VARCHAR(30), ATIVO TINYINT(1) NOT NULL DEFAULT 1,
  COBRAR_BOLETOS TINYINT(1) NULL, DATA_VENCIMENTO DATETIME NULL
);
CREATE TABLE LISTA_PERFIL (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50), DESCRICAO VARCHAR(200));
CREATE TABLE USUARIO (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, LISTA_TURMA_ID BIGINT NULL,
  LISTA_PERFIL_ID BIGINT NOT NULL, LISTA_UNIDADE_ID INT NOT NULL DEFAULT 1, MATRICULA VARCHAR(50), EMAIL VARCHAR(200),
  SENHA VARCHAR(200), NOME VARCHAR(200), URL VARCHAR(500), INATIVO TINYINT(1) NOT NULL DEFAULT 0,
  MASTER TINYINT(1) NOT NULL DEFAULT 0, ONLINE TINYINT(1) NOT NULL DEFAULT 0, MSG_NO_VIEW INT NOT NULL DEFAULT 0,
  TELEFONE VARCHAR(30), CELULAR VARCHAR(30), DATA_NASCIMENTO DATETIME NULL, CPF VARCHAR(20), CEP VARCHAR(10),
  RUA VARCHAR(200), NUMERO INT NULL, BAIRRO VARCHAR(100), CIDADE VARCHAR(100), UF VARCHAR(2), DATA_UPDATE DATETIME NULL
);
CREATE TABLE CONTAS_RECEBER (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, USUARIO_ID BIGINT NULL, INSTITUICAO_ID BIGINT NOT NULL,
  LISTA_SITUACAO_CR_ID BIGINT NULL, DATA_VENCIMENTO DATETIME NULL, DATA_PAGAMENTO DATETIME NULL, VALOR DECIMAL(10,2) NOT NULL DEFAULT 0
);

